civics11AddSection("civics11-farhang",{"id": "civics11-s218-gl3", "title": "Glossary (Farhang): te, Te, jeem", "headingUrdu": "فرہنگ (Glossary): ت، ٹ، ج", "headingPashto": "فرهنګ (Glossary): ت، ټ، ج", "sourceLanguage": "ur", "source": {"pdfPage": 218, "printedPage": "209"}, "auditStatus": "corrected; unresolved source", "flow": [{"type": "paragraphs", "ids": ["civics11-s218-l1", "civics11-s218-g2", "civics11-s218-g3", "civics11-s218-g4", "civics11-s218-g5", "civics11-s218-g6", "civics11-s218-g7", "civics11-s218-g8", "civics11-s218-g9", "civics11-s218-g10", "civics11-s218-l11", "civics11-s218-g12", "civics11-s218-g13", "civics11-s218-l14", "civics11-s218-g15", "civics11-s218-g16", "civics11-s218-g17"]}], "equations": [], "sourceNote": "Printed page 209 (scan 218): glossary entries under the letters “ت”, “ٹ” and “ج” (Progressive … Aggression). The list of entries on this page follows the printed order; the lower part of the page is blank. The scan is skewed. English and Pashto are our translations (need native review); watermark, handwriting and ornamental borders excluded. Printed page = scan − 9.", "review": {"reviewedAtUtc": "2026-10-13T09:48:28.956395+00:00", "scope": "Scan 218 compared with source", "unresolved": "Translations need native review"}, "paras": [
civics11Pair("(ت)","(te)","(ت)",{"id": "civics11-s218-l1", "kind": "heading"}),
civics11Pair("ترقی پسند (Progressive): تبدیلی چاہنے والے۔","Progressive: those who want change","Progressive: هغه څوک چې بدلون غواړي.",{"id": "civics11-s218-g2", "listGroup": "gloss"}),
civics11Pair("پُرتشدد (Violent): خون ریز اور غیر پُرامن۔","Violent: bloody and non-peaceful","Violent: وینې تویوونکی او غیرسوله ییز.",{"id": "civics11-s218-g3", "listGroup": "gloss"}),
civics11Pair("تنقید (Criticism): کسی چیز وغیرہ کا مثبت اور خاص طور پر منفی پہلوؤں پر روشنی ڈالنا۔","Criticism: to throw light on the positive and especially negative aspects of something and so on","Criticism: د کوم شي او نورو پر مثبتو او په ځانګړې توګه منفي اړخونو رڼا اچول.",{"id": "civics11-s218-g4", "listGroup": "gloss"}),
civics11Pair("تفویضِ اختیارات (Delegation of Powers): وہ اختیارات جو ایک اعلیٰ اپنے ماتحت کو عارضی طور پر دے۔","Delegation of Powers: powers that a superior gives to his subordinate temporarily","Delegation of Powers: هغه اختیارات چې یو لوړ چارواکی خپل ماتحت ته په لنډمهاله ډول ورکوي.",{"id": "civics11-s218-g5", "listGroup": "gloss"}),
civics11Pair("ٹیکنوکریٹ (Technocrat): پیشہ ور۔ وہ فرد جو ایک خاص شعبۂ زندگی میں ماہر ہو اور اسی اہلیت کی بنیاد پر اسے نمائندہ مقرر کیا جائے۔","Technocrat: a professional; a person who is expert in a particular field of life and who is appointed a representative on this very ability","Technocrat: مسلکي. هغه فرد چې په ځانګړې ژوندي ډګر کې ماهر وي او د همدې وړتیا پر بنسټ استازی وټاکل شي.",{"id": "civics11-s218-g6", "listGroup": "gloss"}),
civics11Pair("توثیق (Ratification): کسی معاہدہ وغیرہ کی مجاز حکام کی طرف سے آخری منظوری۔","Ratification: final approval of an agreement and so on by the competent authorities","Ratification: د کوم تړون او نورو د مجازو چارواکو له خوا وروستۍ منظوري.",{"id": "civics11-s218-g7", "listGroup": "gloss"}),
civics11Pair("ترقی پذیر (Developing): وہ ممالک جو ترقی کے راستے پر گامزن ہوں۔","Developing: countries that are moving on the path of progress","Developing: هغه هېوادونه چې د پرمختګ په لاره روان وي.",{"id": "civics11-s218-g8", "listGroup": "gloss"}),
civics11Pair("تسلیم کرنا (Recognition): کسی ملک یا حکومت کا دوسرے ممالک یا حکومتوں کی طرف سے تسلیم کرنا اور اس کے ساتھ سفارتی تعلقات قائم کرنا۔","Recognition: the acknowledgement of a country or government by other countries or governments and the establishment of diplomatic relations with it","Recognition: د کوم هېواد یا حکومت د نورو هېوادونو یا حکومتونو له خوا منل او له هغه سره د سفارتي اړیکو جوړول.",{"id": "civics11-s218-g9", "listGroup": "gloss"}),
civics11Pair("تخلیقی (Creative): مثبت، کارآمد، مفید۔","Creative: positive, useful, beneficial","Creative: مثبت، ګټور، ګټه رسوونکی.",{"id": "civics11-s218-g10", "listGroup": "gloss"}),
civics11Pair("(ٹ)","(Te)","(ټ)",{"id": "civics11-s218-l11", "kind": "heading"}),
civics11Pair("ٹیرف (Tariff): کسی ملک کا درآمدات و برآمدات پر عائد کردہ ٹیکس۔","Tariff: tax imposed by a country on imports and exports","Tariff: د کوم هېواد له خوا پر واردات او صادراتو لګول شوی مالیه.",{"id": "civics11-s218-g12", "listGroup": "gloss"}),
civics11Pair("ٹرسٹ (Trust): انسانی فلاح کے لیے با اعتماد افراد کی طرف سے قائم کردہ ادارہ۔ مثلاً انصار برنی ویلفیئر ٹرسٹ۔","Trust: an institution established for human welfare by trustworthy persons; for example Ansar Burney Welfare Trust","Trust: د انساني هوساینې لپاره د باوري کسانو له خوا جوړ شوې اداره. د بېلګې په توګه انصار برني ویلفیر ټرسټ.",{"id": "civics11-s218-g13", "listGroup": "gloss"}),
civics11Pair("(ج)","(jeem)","(ج)",{"id": "civics11-s218-l14", "kind": "heading"}),
civics11Pair("جلاوطن (Exile): آبائی وطن سے باہر۔","Exile: outside one’s ancestral homeland","Exile: له آبایي وطن نه بهر.",{"id": "civics11-s218-g15", "listGroup": "gloss"}),
civics11Pair("جدول (Schedule): کسی دستاویز عام طور پر دستور کے آخر میں تفصیلات پر مبنی حصہ۔","Schedule: a part based on details, generally at the end of a document, usually a constitution","Schedule: د کوم سند معمولاً دستور په پای کې پر تفصیلاتو ولاړه برخه.",{"id": "civics11-s218-g16", "listGroup": "gloss"}),
civics11Pair("جارحیت (Aggression): بلا وجہ کسی ملک میں فوجی مداخلت۔","Aggression: military interference in a country without cause","Aggression: پرته له دلیل په کوم هېواد کې پوځي مداخله.",{"id": "civics11-s218-g17", "listGroup": "gloss"})
]});
